import sys

def inversion_count(arr):
    # arr: list of integers (1-based positions)
    n = len(arr)
    bit = [0] * (n + 2)
    def update(i, v):
        while i <= n:
            bit[i] += v
            i += i & -i
    def query(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s
    inv = 0
    for i in range(n - 1, -1, -1):
        inv += query(arr[i] - 1)
        update(arr[i], 1)
    return inv

def solve():
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    t = int(input_data[0])
    idx = 1
    results = []
    for _ in range(t):
        s = input_data[idx]
        idx += 1
        n = len(s)
        freq = {'r': 0, 'g': 0, 'b': 0}
        for ch in s:
            freq[ch] += 1
        colors = [c for c in 'rgb' if freq[c] > 0]
        if len(colors) == 1:
            results.append('0')
            continue
        # generate permutations of colors
        from itertools import permutations
        best = float('inf')
        for perm in permutations(colors):
            # build position lists for T
            pos_lists = {}
            cur = 1
            for c in perm:
                pos_lists[c] = list(range(cur, cur + freq[c]))
                cur += freq[c]
            # map S to positions
            ptr = {c: 0 for c in colors}
            arr = []
            for ch in s:
                arr.append(pos_lists[ch][ptr[ch]])
                ptr[ch] += 1
            inv = inversion_count(arr)
            if inv < best:
                best = inv
        results.append(str(best))
    sys.stdout.write('\n'.join(results))

if __name__ == "__main__":
    solve()

